+            equalTo("""
+                {
+                  "counts" : {
+                    "driver iterations" : 1
+                  },
+                  "first" : [
+                    {
+                      "reason" : "driver iterations",
+                      "sleep" : "2024-08-13T13:29:23.000Z",
+                      "sleep_millis" : 1723555763000,
+                      "wake" : "2024-08-13T13:31:03.000Z",
+                      "wake_millis" : 1723555863000
+                    }
+                  ],
+                  "last" : [
+                    {
+                      "reason" : "driver iterations",
+                      "sleep" : "2024-08-13T13:29:23.000Z",
