+        builder.field(RETRIEVER_FIELD.getPreferredName());
+        builder.startObject();
+        builder.field(retrieverBuilder.getName(), retrieverBuilder);
+        builder.endObject();
+        builder.field(FIELD_FIELD.getPreferredName(), field);
