+        }
+    }
+
+    @Override
+    protected boolean doEquals(Object other) {
+        RandomRankRetrieverBuilder that = (RandomRankRetrieverBuilder) other;
+        return Objects.equals(retrieverBuilder, that.retrieverBuilder)
